function bindLayout(){const screen=document.getElementById('screen');screen.classList.remove('full-page-mode');screen.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{const input=b.parentElement.querySelector('input');if(Number(b.dataset.step)>0)input.stepUp();else input.stepDown();input.dispatchEvent(new Event('input',{bubbles:true}));});screen.querySelectorAll('[data-admin-page]').forEach(b=>b.onclick=()=>{screen.querySelectorAll('[data-admin-page]').forEach(x=>x.setAttribute('aria-current',x===b?'page':'false'));screen.querySelectorAll('[data-admin-panel]').forEach(x=>x.hidden=x.dataset.adminPanel!==b.dataset.adminPage);screen.querySelector('#adminTitle').textContent=b.textContent;});}

const sessions={}, emails={}; let currentView='home';
try { const saved=JSON.parse(sessionStorage.getItem('mahalak-session-v8')||'{}'); for(const role of ['customer','partner']){if(typeof saved[role]?.token==='string'){sessions[role]=saved[role].token;emails[role]=saved[role].email||'';}} } catch(e){}
function saveSessions(){try{sessionStorage.setItem('mahalak-session-v8',JSON.stringify(Object.fromEntries(['customer','partner'].filter(r=>sessions[r]).map(r=>[r,{token:sessions[r],email:emails[r]||''}]))));}catch(e){}}

async function callServer(path,data,token){let response;try{response=await fetch(MAHALAK_API,{method:'POST',headers:{'Content-Type':'text/plain;charset=UTF-8'},body:JSON.stringify({path,data,token:token||''}),redirect:'follow',credentials:'omit',cache:'no-store'});}catch(e){throw Error('تعذر الاتصال بـ Apps Script. تحقق من النشر وصلاحية الوصول للجميع.');}if(!response.ok)throw Error('تعذر الاتصال: '+response.status);let r;try{r=await response.json();}catch(e){throw Error('استجابة غير صالحة؛ تحقق من نشر Code.gs الجديد.');}if(!r.ok)throw Error(r.error||'تعذر تنفيذ الطلب');return r.result;}
async function proof(password,email,role){if(typeof password!=='string'||password.length<10||password.length>128)throw Error('كلمة المرور من 10 إلى 128 حرفاً');const e=new TextEncoder(),k=await crypto.subtle.importKey('raw',e.encode(password),'PBKDF2',false,['deriveBits']);const bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt:e.encode('MAHALAK-v6:'+role+':'+email.trim().toLowerCase()),iterations:600000,hash:'SHA-256'},k,256);return Array.from(new Uint8Array(bits),x=>x.toString(16).padStart(2,'0')).join('');}
async function request(url,data={}){let [path,q]=url.split('?');data={...Object.fromEntries(new URLSearchParams(q||'')),...(data||{})};let role=path.startsWith('/api/partner/')?'partner':path.startsWith('/api/admin/')||path==='/api/login'?'admin':'customer';if(['/api/register','/api/partner/register','/api/customer/login','/api/partner/login'].includes(path)){let email=String(data.email||'').trim().toLowerCase();data.proof=await proof(data.password,email,role);delete data.password;if(path.endsWith('/login'))emails[role]=email;}if(path==='/api/partner/password'){data.oldProof=await proof(data.old,emails.partner||'',role);data.proof=await proof(data.password,emails.partner||'',role);delete data.old;delete data.password;}let r=await callServer(path,data,sessions[role]);if(r&&r.token)sessions[role]=r.token;if(path.endsWith('/logout')||path==='/api/partner/password')delete sessions[role];saveSessions();return r;}
const photoCache=new Map(), photoQueue=[];let photoRunning=0;
function pumpPhotos(){while(photoRunning<4&&photoQueue.length){const job=photoQueue.shift();photoRunning++;job().finally(()=>{photoRunning--;pumpPhotos()});}}
function displayImage(img,url){img.decoding='async';img.classList.add('photo-loading');if(!/^\/api\/photo\/[a-zA-Z0-9-]+$/.test(url)){img.onload=()=>img.classList.remove('photo-loading');img.onerror=()=>{img.classList.remove('photo-loading');img.classList.add('photo-failed');img.alt='الصورة غير متاحة';};if(typeof url==='string'&&/^https:\/\//i.test(url))img.src=url;else{img.classList.remove('photo-loading');img.classList.add('photo-failed');}return;}if(!photoCache.has(url)){const promise=new Promise((resolve,reject)=>{photoQueue.push(async()=>{try{const d=await request('/api/image',{id:url.split('/').pop()});if(!['image/jpeg','image/png','image/webp'].includes(d.mime))throw Error('صورة غير صالحة');resolve('data:'+d.mime+';base64,'+d.data)}catch(e){reject(e)}});});photoCache.set(url,promise);if(photoCache.size>32)photoCache.delete(photoCache.keys().next().value);pumpPhotos();promise.catch(()=>photoCache.delete(url));}photoCache.get(url).then(src=>{img.onload=img.onerror=()=>img.classList.remove('photo-loading');img.src=src;}).catch(()=>{img.classList.remove('photo-loading');img.alt='الصورة غير متاحة';});}

function premiumLoading(kind='property') {const node=document.createElement('div');node.className='premium-loading '+(kind==='property'?'premium-property-loading':'premium-search-loading');node.setAttribute('role','status');node.innerHTML='<div class="premium-load-head"><span class="premium-spinner" aria-hidden="true"></span><div><strong>'+ (kind==='property'?'جاري تجهيز تفاصيل إقامتك':'جاري البحث عن إقامتك')+'</strong><small>مَحَلّك · نحمّل البيانات والصور</small></div></div><div class="premium-skeleton" aria-hidden="true"><i></i><div><i></i><i></i><i></i></div></div>';return node;}
function premiumError(message,retry){const n=document.createElement('section');n.className='premium-error';const title=document.createElement('strong');title.textContent='تعذر تحميل البيانات';const text=document.createElement('p');text.textContent=message;const b=document.createElement('button');b.type='button';b.textContent='إعادة المحاولة';b.onclick=retry;n.append(title,text,b);return n;}
function searchPrice(h,p){
 const count=Number(p.room_count)||1,nights=(Date.parse(p.departure)-Date.parse(p.arrival))/86400000,price=Number(h.price);
 const wrap=document.createElement('div');wrap.className='search-price-summary';
 const money=n=>n.toLocaleString('ar-SA',{maximumFractionDigits:2})+' ر.س';
 const line=(text,cls)=>{const e=document.createElement('p');e.textContent=text;e.className=cls;wrap.append(e);};
 if(!h.bookable){line('لا يوجد سعر قابل للحجز لهذا الطلب','availability-note');return wrap;}
 if(!Number.isFinite(price)||price<0||!Number.isInteger(nights)||nights<1)return wrap;
 const label=count===1?'غرفة واحدة':count===2?'غرفتين':count+' غرف';
 line(money(price*count*nights),'price');
 line('إجمالي '+label+' · '+nights+' ليلة','search-price-caption');
 line(money(price*count)+' / ليلة لجميع الغرف','search-price-caption');
 line(money(price)+' / غرفة في الليلة','search-price-caption');
 return wrap;
}
