let cachedRows=[],cachedParams=null,resultLayout="list",resultMap=null; function drawResultMap(rows,p){const panel=$("#mapResults");panel.hidden=resultLayout!=="map";$("#results").hidden=resultLayout==="map";if(panel.hidden){panel.querySelector('.v36-map-card')?.remove();if(resultMap){resultMap.remove();resultMap=null;}return;}const node=$("#resultMap"),note=$("#mapNote");if(resultMap){resultMap.remove();resultMap=null;}node.parentElement.querySelector('.v36-map-card')?.remove();node.replaceChildren();const located=rows.filter(validLocation);note.textContent=`${located.length} منشأة على الخريطة · ${rows.length-located.length} بدون إحداثيات مسجلة`;if(!window.L){note.textContent="تعذر تحميل الخريطة. استخدم عرض القائمة.";return;}resultMap=L.map(node).setView([24.5,45],5);L.tileLayer("https://tile.openstreetmap.org/{z}/{x}/{y}.png",{attribution:"© OpenStreetMap contributors",maxZoom:19}).addTo(resultMap);let pts=[];for(const h of located){let xy=[Number(h.latitude),Number(h.longitude)];pts.push(xy);mapHotelMarker(resultMap,resultMap,h,p,xy);}if(pts.length)resultMap.fitBounds(pts,{padding:[30,30],maxZoom:15});}
