async function search(){if(!form.reportValidity())return;const run=++searchRun;let p=params();p.kind=$('#kind').value;p.query=$('#smartQuery').value.trim();$('#message').textContent='جاري البحث...';$('#results').replaceChildren();let loading=premiumLoading('search');$('#results').append(loading);try{let rows=await api('/api/hotels?'+new URLSearchParams(p));if(run!==searchRun||!form.isConnected)return;cachedRows=[...new Map(rows.map(h=>[String(h.id),h])).values()];cachedParams=p;renderResults();renderDiscovery(cachedRows.filter(h=>smartMatch(h,p.query)),p);}catch(e){if(run===searchRun&&form.isConnected){$('#message').textContent='تعذر تحميل نتائج البحث';$('#results').replaceChildren(premiumError(e.message,search));}}}
