// V44: related accommodation, using live inventory for the same stay.
function relatedHotels(rows,h){
 const city=smartTokens(h.city).join(' '),kind=smartTokens(h.kind).join(' '),price=Number(h.price??h.types?.[0]?.price);
 const distance=x=>Number.isFinite(price)&&price>0&&Number(x.price)>0?Math.abs(Math.log(Number(x.price)/price)):1e6;
 return [...new Map(rows.filter(x=>x.id!=null&&String(x.id)!==String(h.id)&&city&&smartTokens(x.city).join(' ')===city).map(x=>[String(x.id),x])).values()].sort((a,b)=>Number(!!b.bookable)-Number(!!a.bookable)||Number(smartTokens(b.kind).join(' ')===kind)-Number(smartTokens(a.kind).join(' ')===kind)||distance(a)-distance(b)||Number(b.rating||0)-Number(a.rating||0)).slice(0,6);
}
