// Partner analytics: scoped data returned by the existing authenticated endpoint.
function hotelAnalyticsModel(d,hotelId,day,from,to){
 const hotels=(d.hotels||[]).filter(h=>!hotelId||String(h.id)===hotelId), ids=new Set(hotels.map(h=>String(h.id)));
 const bookings=(d.bookings||[]).filter(b=>ids.has(String(b.hotel)));
 const period=bookings.filter(b=>String(b.arrival)>=from&&String(b.arrival)<=to);
 const confirmed=period.filter(b=>b.status==='confirmed');
 const rooms=hotels.map(h=>{const list=bookings.filter(b=>String(b.hotel)===String(h.id)&&String(b.arrival)<=day&&String(b.departure)>day);const total=Math.max(0,Number(h.rooms)||0),occupied=list.filter(b=>b.status==='confirmed').length,held=list.filter(b=>b.status==='pending').length;return {name:h.name,total,occupied,held,free:Math.max(0,total-occupied-held),over:Math.max(0,occupied+held-total)}});
 return {period,confirmed,rooms};
}
function renderHotelAnalytics(d){
 const $=id=>document.getElementById(id);if(!$('reportHotel'))return;
 const today=new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Riyadh'}).format(new Date());
 for(const id of ['reportHotel','roomHotel']){const s=$(id),prev=s.value;s.replaceChildren(new Option('كل منشآتي',''),...d.hotels.map(h=>new Option(h.name,String(h.id))));if([...s.options].some(o=>o.value===prev))s.value=prev;}
 $('reportFrom').value||=today.slice(0,8)+'01';$('reportTo').value||=today;$('roomDate').value||=today;
 const money=n=>new Intl.NumberFormat('ar-SA',{style:'currency',currency:'SAR'}).format(n);
 function metrics(id,items){$(id).replaceChildren(...items.map(([label,value])=>{let box=document.createElement('div');box.className='hotel-metric';let l=document.createElement('small'),v=document.createElement('strong');l.textContent=label;v.textContent=value;box.append(l,v);return box;}));}
 function report(){const from=$('reportFrom').value,to=$('reportTo').value;if(!from||!to||from>to){$('reportMetrics').replaceChildren();$('reportNote').textContent='حدد فترة صحيحة';return;}const {period,confirmed}=hotelAnalyticsModel(d,$('reportHotel').value,today,from,to);metrics('reportMetrics',[['إجمالي الطلبات',period.length],['مؤكدة',confirmed.length],['بانتظار التأكيد',period.filter(b=>b.status==='pending').length],['ملغاة',period.filter(b=>b.status==='cancelled').length],['قيمة الحجوزات المؤكدة',money(confirmed.reduce((s,b)=>s+(Number(b.total)||0),0))]]);$('reportNote').textContent='الفترة حسب تاريخ الوصول. القيمة ليست مبالغ محصلة أو صافي أرباح.';}
 function room(){const day=$('roomDate').value;if(!day){$('roomMetrics').replaceChildren();$('roomList').textContent='اختر التاريخ';return;}const {rooms}=hotelAnalyticsModel(d,$('roomHotel').value,day,'','');const sum=k=>rooms.reduce((s,r)=>s+r[k],0);metrics('roomMetrics',[['إجمالي الغرف',sum('total')],['محجوزة مؤكدة',sum('occupied')],['محجوزة مؤقتاً',sum('held')],['متاحة للحجز',sum('free')],['نسبة الحجز المؤكد',sum('total')?Math.round(sum('occupied')/sum('total')*100)+'%':'—']]);$('roomList').replaceChildren(...rooms.map(r=>{let el=document.createElement('div');el.className='hotel-room-row';let h=document.createElement('strong');h.textContent=r.name;el.append(h);for(const [k,label] of [['free','متاحة'],['occupied','مؤكدة'],['held','معلقة']]){let b=document.createElement('span');b.className='room-'+k;b.textContent=label+' · '+r[k];el.append(b);}if(r.over){let w=document.createElement('p');w.textContent='تنبيه: تجاوز المخزون بـ '+r.over;el.append(w);}return el;}));if(!rooms.length)$('roomList').textContent='لا توجد منشآت مسجلة';}
 for(const id of ['reportHotel','reportFrom','reportTo'])$(id).onchange=report;for(const id of ['roomHotel','roomDate'])$(id).onchange=room;
 const tabs=[...document.querySelectorAll('[data-hotel-tab]')],pages=[...document.querySelectorAll('[data-hotel-page]')];function tab(key){for(const b of tabs)b.setAttribute('aria-pressed',String(b.dataset.hotelTab===key));for(const p of pages)p.hidden=p.dataset.hotelPage!==key;}
 const selected=tabs.find(b=>b.getAttribute('aria-pressed')==='true')?.dataset.hotelTab||'reports';for(const b of tabs)b.onclick=()=>tab(b.dataset.hotelTab);tab(selected);$('reportPrint').onclick=()=>window.print();report();room();
}

// Full-page photo viewer: no nested scrolling or modal required.
function showPhotos(images,index,title){
 const screen=document.getElementById('screen'),original=[...screen.children],previous=window.scrollY;
 const page=document.createElement('main');page.className='photo-viewer';
 const visibility=original.map(n=>n.hidden);original.forEach(n=>n.hidden=true);screen.append(page);
 const make=(tag,text)=>{let n=document.createElement(tag);n.textContent=text||'';return n};
 const back=make('button','رجوع إلى تفاصيل المنشأة');back.type='button';back.onclick=()=>{page.remove();original.forEach((n,i)=>n.hidden=visibility[i]);window.scrollTo(0,previous)};
 const heading=make('h1','صور '+title),figure=make('figure'),image=make('img'),caption=make('figcaption'),controls=make('div');controls.className='photo-controls';
 let prev=make('button','الصورة السابقة'),next=make('button','الصورة التالية');prev.type=next.type='button';
 let run=0;function draw(){const seq=++run;image.removeAttribute('src');image.alt='صورة '+title;caption.textContent=(index+1)+' / '+images.length;prev.disabled=index===0;next.disabled=index===images.length-1;let url=images[index];if(/^\/api\/photo\/[a-zA-Z0-9-]+$/.test(url))request('/api/image',{id:url.split('/').pop()}).then(d=>{if(seq===run&&page.isConnected&&['image/jpeg','image/png','image/webp'].includes(d.mime))image.src='data:'+d.mime+';base64,'+d.data;}).catch(()=>{if(seq===run)image.alt='الصورة غير متاحة';});}
 prev.onclick=()=>{if(index>0){index--;draw()}};next.onclick=()=>{if(index<images.length-1){index++;draw()}};figure.append(image,caption);controls.append(prev,next);const detail=make('section');detail.className='viewer-detail';detail.append(heading,make('p','استكشف تفاصيل المكان، وتنقّل بين الصور.'),controls);const spread=make('div');spread.className='viewer-spread';spread.append(figure,detail);page.append(back,spread);draw();window.scrollTo(0,0);
}

function attachHotelLocation(form,h){if(form.querySelector('.location-editor'))return;const wrap=document.createElement('section');wrap.className='location-editor';const title=document.createElement('h3');title.textContent='موقع المنشأة على الخريطة';wrap.append(title);for(const [key,label] of [['address','العنوان'],['latitude','خط العرض'],['longitude','خط الطول']]){if(form.elements[key])continue;const l=document.createElement('label'),i=document.createElement('input');l.textContent=label;i.name=key;i.value=h[key]??'';if(key!=='address'){i.type='number';i.step='any';i.min=key==='latitude'?-90:-180;i.max=key==='latitude'?90:180;}l.append(i);wrap.append(l);}const open=document.createElement('button'),gps=document.createElement('button'),node=document.createElement('div'),note=document.createElement('p');open.type=gps.type='button';open.textContent='تحديد الموقع على الخريطة';gps.textContent='استخدام موقعي الحالي';node.className='hotel-location-map';node.hidden=true;note.setAttribute('role','status');wrap.append(open,gps,node,note);form.insertBefore(wrap,form.querySelector('button[type=submit]')||null);let map,marker;const point=()=>({latitude:form.elements.latitude.value,longitude:form.elements.longitude.value});function set(lat,lng){form.elements.latitude.value=lat.toFixed(6);form.elements.longitude.value=lng.toFixed(6);if(map){if(marker)marker.setLatLng([lat,lng]);else{marker=L.marker([lat,lng],{draggable:true,icon:L.divIcon({className:'mh-location-pin',html:'<span></span>',iconSize:[34,42],iconAnchor:[17,40]})}).addTo(map);marker.on('dragend',()=>{const a=marker.getLatLng();set(a.lat,a.lng)});}}note.textContent='تم تحديد الموقع؛ احفظ المنشأة لتثبيته.';}function show(){if(!window.L){note.textContent='تعذر تحميل الخريطة. يمكنك إدخال الإحداثيات يدوياً.';return;}node.hidden=false;if(!map){const p=point(),ok=validLocation(p);map=L.map(node).setView(ok?[Number(p.latitude),Number(p.longitude)]:[24.5,45],ok?15:5);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap contributors',maxZoom:19}).addTo(map);map.on('click',e=>set(e.latlng.lat,e.latlng.lng));if(ok)set(Number(p.latitude),Number(p.longitude));}requestAnimationFrame(()=>map.invalidateSize());}open.onclick=show;gps.onclick=()=>{if(!navigator.geolocation){note.textContent='الموقع غير مدعوم';return;}navigator.geolocation.getCurrentPosition(p=>{show();set(p.coords.latitude,p.coords.longitude);if(map)map.setView([p.coords.latitude,p.coords.longitude],16)},()=>note.textContent='تعذر تحديد موقعك؛ اختر الموقع يدوياً.',{timeout:15000});};form.addEventListener('reset',()=>{if(map){map.remove();map=null;marker=null;}node.hidden=true;note.textContent='';});for(const key of ['latitude','longitude'])form.elements[key].addEventListener('change',()=>{const p=point();if(map&&validLocation(p)){set(Number(p.latitude),Number(p.longitude));map.setView([Number(p.latitude),Number(p.longitude)],15);}});}

// V39: a single form with independent full-width steps; fields remain in DOM for FormData.
function propertyWizard(form){
 if(!form||form.dataset.wizard)return;form.dataset.wizard='1';form.classList.add('property-wizard');
 const make=(tag,text,cls)=>{const n=document.createElement(tag);if(text)n.textContent=text;if(cls)n.className=cls;return n};
 const submit=form.querySelector('button:not([type]),button[type=submit]');if(!submit)return;submit.type='submit';
 const groups=[['البيانات الأساسية','اسم المنشأة ونوعها ووصفها', ['name','city','kind','description']],['الأسعار والسعة','حدد سعر الليلة وإجمالي الغرف',['price','rooms']],['المرافق والسياسات','اختر الخدمات المتوفرة وسياسة الحيوانات',['amenities','pets_allowed']],['الموقع','حدد العنوان وموقع المنشأة على الخريطة',['address','latitude','longitude']],['الصور','أضف صور المنشأة من الألبوم',[]]];
 const sections=groups.map(([title,desc])=>{const n=make('section','','pw-step');n.append(make('h2',title),make('p',desc,'pw-muted'));return n});
 for(const child of [...form.children]){if(child===submit)continue;let idx=child.matches('.location-editor')?3:child.matches('#preview')||child.querySelector('input[type=file]')?4:groups.findIndex(g=>g[2].some(k=>child.matches('[name='+k+']')||child.querySelector('[name='+k+']')));if(idx<0)idx=child.matches('.amenity-picker,strong')?2:0;sections[idx].append(child)}
 const active=sections.map((n,i)=>({n,i})).filter(x=>x.n.children.length>2);const review=make('section','','pw-step');review.append(make('h2','المراجعة والحفظ'),make('p','راجع البيانات قبل حفظ المنشأة.','pw-muted'));const recap=make('dl','','pw-recap');review.append(recap);active.push({n:review,i:5});
 const bar=make('nav','','pw-nav'), head=make('div','','pw-head'), progress=make('p','','pw-muted'), track=make('div','','pw-track'),fill=make('div');track.append(fill);head.append(make('h2','إدارة بيانات المنشأة'),progress,track);const body=make('div','','pw-body'), foot=make('div','','pw-actions'),prev=make('button','السابق','secondary'),next=make('button','التالي');prev.type=next.type='button';foot.append(prev,next,submit);form.append(head,bar,body,foot);active.forEach(x=>body.append(x.n));let step=0;
 const validate=i=>{for(const input of active[i].n.querySelectorAll('input,select,textarea'))if(!input.checkValidity()){input.reportValidity();return false}return true};
 const show=(i,focus=false)=>{step=i;active.forEach((x,j)=>x.n.hidden=j!==i);bar.querySelectorAll('button').forEach((b,j)=>{b.setAttribute('aria-current',j===i?'step':'false')});progress.textContent=`الخطوة ${i+1} من ${active.length}`;fill.style.width=(100*(i+1)/active.length)+'%';prev.hidden=i===0;next.hidden=i===active.length-1;submit.hidden=i!==active.length-1;if(i===active.length-1){recap.replaceChildren();for(const [key,label] of [['name','الاسم'],['city','المدينة'],['kind','النوع'],['price','سعر الليلة (ر.س)'],['rooms','عدد الغرف'],['description','الوصف'],['address','العنوان'],['amenities','المرافق']]){const f=form.elements[key];if(f)recap.append(make('dt',label),make('dd',f.value||'—'));}}if(focus){active[i].n.querySelector('h2').tabIndex=-1;active[i].n.querySelector('h2').focus({preventScroll:true});form.scrollIntoView({block:'start'});} };
 active.forEach((x,j)=>{const b=make('button',`${j+1} · ${x.i===5?'المراجعة':groups[x.i][0]}`);b.type='button';b.onclick=()=>{if(j>step){for(let k=step;k<j;k++){show(k);if(!validate(k))return;}}show(j,true)};bar.append(b)});prev.onclick=()=>show(step-1,true);next.onclick=()=>{if(validate(step))show(step+1,true)};
 form.addEventListener('submit',e=>{if(step!==active.length-1){e.preventDefault();e.stopImmediatePropagation();if(validate(step))show(step+1,true)}},true);
 form.addEventListener('invalid',e=>{const j=active.findIndex(x=>x.n.contains(e.target));if(j>=0&&j!==step)show(j)},true);form.addEventListener('reset',()=>setTimeout(()=>show(0),0));show(0);
}

function stayNode(tag,text='',cls=''){let n=document.createElement(tag);n.textContent=text;n.className=cls;return n;}
function stayToday(){return new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Riyadh'}).format(new Date());}
function stayEligible(b){return b.status==='confirmed'&&!b.checked_out_at&&Number(b.checked_out_rooms||0)===0&&b.departure>=stayToday();}
function stayStatus(b){return ({pending:'طلب تمديد بانتظار الفندق',approved:'تم اعتماد التمديد',rejected:'تم رفض التمديد',withdrawn:'تم سحب طلب التمديد'})[b.extension_status]||'';}
function stayButton(t,fn,notice){let a=stayNode('button',t,'secondary');a.type='button';a.onclick=async()=>{a.disabled=true;try{await fn()}catch(e){notice.textContent=e.message}finally{a.disabled=false}};return a;}
function stayCustomerPanel(b,reload){let box=stayNode('section','','stay-panel'),notice=stayNode('p','','stay-notice');notice.setAttribute('role','status');if(stayStatus(b))box.append(stayNode('strong',stayStatus(b)),stayNode('p','التاريخ المطلوب: '+b.extension_departure+' · '+b.extension_cost+' ر.س'));if(b.extension_reason)box.append(stayNode('p',b.extension_reason));if(b.stay_intent==='depart')box.append(stayNode('p','تم إبلاغ الفندق بأنك ستغادر في الموعد'));if(!stayEligible(b)){box.hidden=!box.children.length;return box;}box.append(stayNode('h4','إدارة إقامتك'));let call=(action,data={})=>request('/api/customer/stay',{id:String(b.id),action,...data});if(b.extension_status==='pending'){box.append(stayButton('سحب طلب التمديد',async()=>{await call('withdraw');await reload()},notice));}else{let date=stayNode('input');date.type='date';date.min=new Date(Date.parse(b.departure)+86400000).toISOString().slice(0,10);date.max=new Date(Date.parse(b.departure)+30*86400000).toISOString().slice(0,10);date.value=date.min;let label=stayNode('label','تاريخ المغادرة الجديد');label.append(date);let confirm=stayButton('إرسال طلب التمديد',async()=>{await call('request',{departure:date.value,cost:quote.cost});await reload()},notice),quote;confirm.hidden=true;date.onchange=()=>{confirm.hidden=true;quote=null;notice.textContent='';};box.append(label,stayButton('احسب تكلفة التمديد',async()=>{confirm.hidden=true;let selected=date.value;quote=await call('quote',{departure:selected});if(date.value!==selected)return;notice.textContent=quote.nights+' ليلة إضافية · '+quote.cost+' ر.س | الإجمالي الجديد '+quote.total+' ر.س. يخضع لموافقة الفندق.';confirm.hidden=false;},notice),confirm);}box.append(stayButton('سأغادر في الموعد',async()=>{if(!window.confirm('إبلاغ الفندق بالمغادرة في الموعد وسحب أي تمديد معلق؟'))return;await call('depart');await reload()},notice),notice);return box;}
function stayPartnerPanel(b,api,reload,phoneFn){let box=stayNode('section','','stay-panel'),notice=stayNode('p','','stay-notice');notice.setAttribute('role','status');if(stayStatus(b))box.append(stayNode('strong',stayStatus(b)),stayNode('p','المغادرة المطلوبة: '+b.extension_departure+' · تكلفة إضافية '+b.extension_cost+' ر.س'));if(b.stay_intent==='depart')box.append(stayNode('p','الضيف اختار المغادرة في الموعد'));if(!stayEligible(b)){box.hidden=!box.children.length;return box;}box.append(stayNode('h4','متابعة الإقامة والمغادرة'));let phone=phoneFn(b.phone);if(phone){let link=stayNode('a','اسأل الضيف: تمديد أم مغادرة؟','button secondary');let url=new URL(location.href);url.hash='trips';let text='مَحَلّك | متابعة إقامتك\nعزيزي '+b.guest+'، نأمل أن تكون إقامتك في '+b.name+' ممتعة. موعد مغادرتك '+b.departure+'. هل ترغب في تمديد الإقامة أم المغادرة في الموعد؟ يمكنك اختيار ذلك من حجوزاتي: '+url.href+' أو الرد على هذه الرسالة. شكراً لك.';link.href='https://web.whatsapp.com/send?phone='+phone+'&text='+encodeURIComponent(text);link.target='_blank';link.rel='noopener noreferrer';box.append(link);}if(b.extension_status==='pending'){box.append(stayButton('اعتماد التمديد',async()=>{if(!window.confirm('اعتماد التمديد وتحديث إجمالي الحجز؟'))return;await api('stay',{id:String(b.id),action:'approve'});await reload()},notice),stayButton('رفض الطلب',async()=>{let reason=window.prompt('سبب رفض التمديد','الغرفة غير متاحة');if(reason===null)return;await api('stay',{id:String(b.id),action:'reject',reason});await reload()},notice));}box.append(notice);return box;}
